CREATE OR REPLACE FUNCTION public.standard_delivery_fee() RETURNS numeric LANGUAGE sql STABLE SET search_path=public AS $$ SELECT coalesce((SELECT CASE WHEN value ~ '^\d+(\.\d{1,2})?$' THEN value::numeric END FROM public.store_settings WHERE key='delivery_fee'),250::numeric) $$;
GRANT EXECUTE ON FUNCTION public.standard_delivery_fee() TO anon,authenticated,service_role;
DO $$ DECLARE src text; BEGIN
 src:=pg_get_functiondef('public.create_order_with_plan(jsonb)'::regprocedure); src:=replace(src,'then 150 else 0 end','then public.standard_delivery_fee() else 0 end'); EXECUTE src;
 src:=pg_get_functiondef('public.membership_refresh(uuid)'::regprocedure); src:=replace(src,'v_carry := least(v_remaining, v_old.max_carry_forward);','v_carry := 0;'); EXECUTE src;
 src:=pg_get_functiondef('public.orders_membership_credit()'::regprocedure); src:=replace(src,$s$new.status in ('cancelled','refunded')$s$,$s$new.status in ('cancelled','refunded','failed_delivery')$s$); src:=replace(src,$s$coalesce((select value from public.store_settings where key = 'membership_restore_credit_on_refund'), 'true') = 'true'$s$,'false'); EXECUTE src;
 src:=pg_get_functiondef('public.order_status_changed()'::regprocedure); src:=replace(src,$s$new.status in ('cancelled','refunded')$s$,$s$new.status in ('cancelled','refunded','failed_delivery')$s$); src:=replace(src,$s$new.status = 'cancelled' and old.status in ('pending_confirmation','confirmed','preparing')$s$,$s$new.status in ('cancelled','failed_delivery') and old.status in ('pending_confirmation','confirmed','preparing','ready_for_dispatch','out_for_delivery')$s$); EXECUTE src;
END $$;
CREATE OR REPLACE FUNCTION public.valid_order_transition(old_status text,new_status text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT old_status=new_status OR CASE old_status WHEN 'pending_confirmation' THEN new_status IN ('confirmed','cancelled') WHEN 'confirmed' THEN new_status IN ('preparing','cancelled') WHEN 'preparing' THEN new_status IN ('ready_for_dispatch','out_for_delivery','cancelled') WHEN 'ready_for_dispatch' THEN new_status IN ('out_for_delivery','cancelled') WHEN 'out_for_delivery' THEN new_status IN ('delivered','failed_delivery','cancelled') WHEN 'delivered' THEN new_status IN ('return_requested','refunded') WHEN 'return_requested' THEN new_status IN ('delivered','returned','refunded') WHEN 'returned' THEN new_status='refunded' ELSE false END $$;
CREATE OR REPLACE FUNCTION public.guard_order_transition() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.valid_order_transition(old.status::text,new.status::text) THEN RAISE EXCEPTION 'INVALID_ORDER_TRANSITION'; END IF; IF new.status='delivered' AND old.status IS DISTINCT FROM 'return_requested' THEN new.payment_status:='paid'; END IF; RETURN new; END $$;
CREATE TRIGGER aaa_order_transition BEFORE UPDATE OF status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.guard_order_transition();
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS low_stock_threshold integer NOT NULL DEFAULT 5;
CREATE TABLE public.inventory_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES public.products(id),order_id uuid REFERENCES public.orders(id),quantity_delta integer NOT NULL,available_after integer NOT NULL,kind text NOT NULL,reason text NOT NULL,actor uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.inventory_transactions TO authenticated; GRANT ALL ON public.inventory_transactions TO service_role;
ALTER TABLE public.inventory_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY inventory_admin_read ON public.inventory_transactions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX inventory_product_time ON public.inventory_transactions(product_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.record_inventory_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF old.stock_quantity IS DISTINCT FROM new.stock_quantity THEN INSERT INTO public.inventory_transactions(product_id,order_id,quantity_delta,available_after,kind,reason,actor) VALUES(new.id,nullif(current_setting('sabtk.order_id',true),'')::uuid,new.stock_quantity-old.stock_quantity,new.stock_quantity,coalesce(nullif(current_setting('sabtk.stock_kind',true),''),'adjustment'),coalesce(nullif(current_setting('sabtk.stock_reason',true),''),'Product stock update'),auth.uid()); END IF; RETURN new; END $$;
CREATE TRIGGER inventory_product_changes AFTER UPDATE OF stock_quantity ON public.products FOR EACH ROW EXECUTE FUNCTION public.record_inventory_change();
DO $$ DECLARE src text; BEGIN src:=pg_get_functiondef('public.create_order(jsonb)'::regprocedure); src:=replace(src,'for v_item in select * from jsonb_array_elements(p->''items'') loop','perform set_config(''sabtk.order_id'',v_order_id::text,true); perform set_config(''sabtk.stock_kind'',''reserve'',true); perform set_config(''sabtk.stock_reason'',''Stock reserved for ''||v_number,true); for v_item in select * from jsonb_array_elements(p->''items'') loop'); EXECUTE src;
 src:=pg_get_functiondef('public.order_status_changed()'::regprocedure); src:=replace(src,'for v_item in select product_id, quantity from public.order_items where order_id = new.id loop','perform set_config(''sabtk.order_id'',new.id::text,true); perform set_config(''sabtk.stock_kind'',''release'',true); perform set_config(''sabtk.stock_reason'',''Reservation released: ''||new.status::text,true); for v_item in select product_id, quantity from public.order_items where order_id = new.id loop'); EXECUTE src; END $$;
CREATE OR REPLACE FUNCTION public.adjust_inventory(p_product uuid,p_delta integer,p_threshold integer,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF length(trim(p_reason))<5 OR p_threshold<0 THEN RAISE EXCEPTION 'Reason and valid threshold required'; END IF; PERFORM set_config('sabtk.stock_kind','adjustment',true); PERFORM set_config('sabtk.stock_reason',p_reason,true); PERFORM set_config('sabtk.order_id','',true); UPDATE public.products SET stock_quantity=stock_quantity+p_delta,low_stock_threshold=p_threshold WHERE id=p_product AND stock_quantity+p_delta>=0; IF NOT FOUND THEN RAISE EXCEPTION 'Invalid stock adjustment'; END IF; END $$;
REVOKE ALL ON FUNCTION public.adjust_inventory(uuid,integer,integer,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.adjust_inventory(uuid,integer,integer,text) TO authenticated;
CREATE TRIGGER inventory_audit AFTER INSERT ON public.inventory_transactions FOR EACH ROW EXECUTE FUNCTION public.audit_row();